// Import of required libraries
import { test, expect, SkyrampClient, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import {
    createUser,
    createCollection,
    updateCollection,
    deleteCollectionMember,
    getCollectionMembers,
    deleteCollection,
    deleteUser,
} from './skyrampUtils';

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const collaboratorUsername = uniqueSuffix("removalcollab");
    const collectionAName = uniqueSuffix("Removal Scope A");
    const collectionBName = uniqueSuffix("Removal Scope B");

    const usersPostResponse = await createUser(client, headers, collaboratorUsername);
    expect(usersPostResponse.statusCode, 'status code').toBe(201);
    expect(getResponseValue(usersPostResponse, "response.username"), 'username').toBe(collaboratorUsername);
    expect(getResponseValue(usersPostResponse, "response.id"), 'user id').toBeGreaterThan(0);
    // The collaborator's id comes from the create response, never a hardcoded id.
    const userId = getResponseValue(usersPostResponse, "response.id");

    const collectionsPostResponse = await createCollection(client, headers, collectionAName);
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'collection A name').toBe(collectionAName);
    expect(getResponseValue(collectionsPostResponse, "response.id"), 'collection A id').toBeGreaterThan(0);
    expect(getResponseValue(collectionsPostResponse, "response.members").length, 'collection A starts with no members').toBe(0);
    const collectionAId = getResponseValue(collectionsPostResponse, "response.id");

    const collectionsPost1Response = await createCollection(client, headers, collectionBName);
    expect(collectionsPost1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPost1Response, "response.name"), 'collection B name').toBe(collectionBName);
    expect(getResponseValue(collectionsPost1Response, "response.id"), 'collection B id').toBeGreaterThan(0);
    expect(getResponseValue(collectionsPost1Response, "response.members").length, 'collection B starts with no members').toBe(0);
    const collectionBId = getResponseValue(collectionsPost1Response, "response.id");

    const collectionsCollectionsPutResponse = await updateCollection(client, headers, collectionAId, collectionAName, userId);
    expect(collectionsCollectionsPutResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.members").length, 'collection A member count').toBe(1);
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.members.0.userId"), 'collection A member').toBe(userId);
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.members.0.canCreate"), 'canCreate').toBe(true);
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.members.0.canUpdate"), 'canUpdate').toBe(true);
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.members.0.canDelete"), 'canDelete').toBe(false);
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.members.1"), 'no second member on A').toBeNull();

    const collectionsCollectionsPut1Response = await updateCollection(client, headers, collectionBId, collectionBName, userId);
    expect(collectionsCollectionsPut1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsPut1Response, "response.members").length, 'collection B member count').toBe(1);
    expect(getResponseValue(collectionsCollectionsPut1Response, "response.members.0.userId"), 'collection B member').toBe(userId);
    expect(getResponseValue(collectionsCollectionsPut1Response, "response.members.0.collectionId"), 'collection B membership collection').toBe(collectionBId);
    expect(getResponseValue(collectionsCollectionsPut1Response, "response.members.1"), 'no second member on B').toBeNull();

    // Remove the collaborator from collection A ONLY.
    const membersDeleteResponse = await deleteCollectionMember(client, headers, collectionAId, userId);
    expect(membersDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(membersDeleteResponse, "response"), 'removal message').toBe("Member removed.");

    // Collection B is a different collection and must be untouched by that removal.
    const membersGetResponse = await getCollectionMembers(client, headers, collectionBId);
    expect(membersGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(membersGetResponse, "response").length, 'collection B member count after removing from A').toBe(1);
    expect(getResponseValue(membersGetResponse, "response.0.userId"), 'collection B still lists the collaborator').toBe(userId);
    expect(getResponseValue(membersGetResponse, "response.0.collectionId"), 'membership belongs to collection B').toBe(collectionBId);
    expect(getResponseValue(membersGetResponse, "response.0.user.name"), 'member name').toBe("Removal Collaborator");
    expect(getResponseValue(membersGetResponse, "response.0.role"), 'membership row carries a role').not.toBeNull();
    expect(getResponseValue(membersGetResponse, "response.1"), 'no second member').toBeNull();

    const collectionsCollectionsDeleteResponse = await deleteCollection(client, headers, collectionAId);
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'deleted collection A id').toBe(collectionAId);

    const collectionsCollectionsDelete1Response = await deleteCollection(client, headers, collectionBId);
    expect(collectionsCollectionsDelete1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsDelete1Response, "response.id"), 'deleted collection B id').toBe(collectionBId);

    const usersUsersDeleteResponse = await deleteUser(client, headers, userId);
    expect(usersUsersDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(usersUsersDeleteResponse, "response"), 'user deletion message').toBe("User account and all related data deleted successfully.");
});
